import pathlib,json,hashlib,stat,subprocess,sys,platform; q=pathlib.Path("evidence://campaign"); print("ENV",sys.version,platform.platform());
for f in ["advisories/heldout-b/H1/assessment.md","advisories/heldout-b/H2/assessment.md","advisories/heldout-b/H3/assessment.md","advisories/heldout-b/RESULT.json","private/heldout-b/maps.json","scopes/heldout.json","protocol/QUALITY.md","protocol/SCORING.json","protocol/OPERATIONS.md"]:
 p=q/f; s=p.lstat(); assert stat.S_ISREG(s.st_mode) and not any(x.is_symlink() for x in [p,*p.parents]); print(f,s.st_size,hashlib.sha256(p.read_bytes()).hexdigest())
lock=json.loads((q/"LOCK.json").read_text()); print("LOCK_MATCH",all(hashlib.sha256((q/"locked/proof-readiness"/f).read_bytes()).hexdigest()==h for f,h in lock["skill_files_sha256"].items()))
for r in json.loads((q/"scopes/heldout.json").read_text())["records"]:
 files=r["production_files"]+r["immediate_caller_or_helper_files"]+r["configuration_files"]+r["test_or_requirement_files"]; print(r["id"])
 for f in files:
  p=pathlib.Path(r["root"])/f; s=p.lstat(); assert stat.S_ISREG(s.st_mode) and s.st_size<=262144 and not any(x.is_symlink() for x in [p,*p.parents]); print(f,hashlib.sha256(p.read_bytes()).hexdigest())
 for args in [["rev-parse","HEAD","HEAD^{tree}"],["diff","--exit-code","HEAD","--",*files]]:
  cmd=["git","--no-pager","--no-optional-locks","-C",r["root"],*args]; p=subprocess.run(cmd,capture_output=True,text=True); print("CMD",cmd,"EXIT",p.returncode,"OUT",repr(p.stdout),"ERR",repr(p.stderr))

